import re


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "" if absent.

    html is an already-fetched page; this function must not use the network.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_title_of_returns_title_text() -> None:
    assert title_of("<html><head><title>Hi</title></head></html>") == "Hi"


def test_title_of_without_title_returns_empty() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_title_of_unclosed_title_returns_empty() -> None:
    assert title_of("<html><head><title>Hi") == ""
